def _validate_request(data, signature):
    """Validate the request payload and its signature.

    A missing payload is a malformed request, while a missing or unverifiable
    signature is an authentication failure. Signature verification is kept in
    one place so every request follows the same validation path.
    """
    if data is None:
        raise ValueError("request data is required")

    if signature is None or not verify_signature(data, signature):
        raise PermissionError("invalid signature")


def handle_request(data, signature):
    """Validate the request and process its payload."""
    _validate_request(data, signature)
    return process(data)

